import { Box, defineTask } from '@caemble/core'
// CSG surfaces retain their meaning when spatialResolution changes.
export default defineTask({
  kernel: { name: 'structural-mechanics', version: '6.1.0' },
  lengthUnit: 'm',
  config: () => ({
    parameters: {
      analysis: 'static',
      geometricNonlinear: false,
      relativeTolerance: {
        dtype: 'float64',
        value: 1e-8,
        quantityKind: 'Dimensionless',
        unit: '1',
      },
      maxIterations: 40,
      spatialResolution: {
        dtype: 'float64',
        value: 0.15,
        quantityKind: 'Length',
        unit: 'm',
      },
    },
    initializations: [
      {
        methodId: 'fea.body',
        target: ['experiment.geometry.body'],
        parameters: {},
      },
    ],
    boundaryConditions: [
      {
        methodId: 'fea.fixed',
        target: ['experiment.surface.fixed'],
        parameters: {
          components: {
            dtype: 'string',
            value: ['x', 'y', 'z'],
            axes: [{ length: 3 }],
          },
        },
      },
      {
        methodId: 'fea.surface-load',
        target: ['experiment.surface.loaded'],
        parameters: {
          force: {
            dtype: 'float64',
            value: [1000, 0, 0],
            quantityKind: 'mechanics.ForceMagnitude',
            unit: 'N',
            axes: [{ length: 3 }],
          },
          moment: {
            dtype: 'float64',
            value: [0, 0, 0],
            quantityKind: 'mechanics.BendingMomentOfForce',
            unit: 'N.m',
            axes: [{ length: 3 }],
          },
          referencePoint: {
            dtype: 'float64',
            value: [1, 0, 0],
            quantityKind: 'Length',
            unit: 'm',
            axes: [{ length: 3 }],
          },
        },
      },
    ],
    outputs: [
      {
        methodId: 'fea.displacement',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [12, 6, 6] },
        key: 'displacement',
      },
      {
        methodId: 'fea.reaction',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [1, 1, 1] },
        key: 'reaction',
      },
      {
        methodId: 'fea.stress-field',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [12, 6, 6] },
        key: 'stress',
      },
      {
        methodId: 'fea.stress-field',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [12, 6, 6] },
        key: 'stressField',
      },
    ],
    exports: [],
  }),
  geometry: () => (
    <Box
      id="output-grid"
      position={[0.5, 0, 0]}
      size={[1.001, 0.30029999999999996, 0.30029999999999996]}
    />
  ),
  geometryGroup: { outputGrid: ['output-grid'] },
})

